"""Verify prepared production contains the Steam fixes and no external ReShade path."""
from pathlib import Path
import argparse
import hashlib
import json

ROOT = Path(__file__).resolve().parents[1]

def verify(source):
    src = source / 'bridge/src'
    forbidden = (b'ldb_reshade', b'reshadeExternalInput', b'externalReShade',
                 b'setExternal(', b'externalActive(', b'refreshExternalInput',
                 b'ReShadeLDB', b'VK_LAYER_LDB_reshade', b'LDBReShadeInputV1')
    scanned = 0
    for p in src.rglob('*'):
        if not p.is_file(): continue
        raw = p.read_bytes()
        for marker in forbidden:
            if marker in raw: raise ValueError(f'Experimental ReShade marker remains in {p}: {marker!r}')
        scanned += 1
    for name in ('client/reshade_input_client.h', 'util/reshade_external_input.h',
                 'util/reshade_layer_environment.h', 'util/ldb_external_wire.h'):
        if (src / name).exists(): raise ValueError(f'Removed header remains: {name}')
    requirements = {
        'client/window.cpp': ('applySteamActivation(active)', 'RemixState::setSteam(active)',
                              'LDB_STEAM_CAPTURE_NOTIFY_V1', 'client.steamWindowDiagnostics'),
        'client/remix_state.h': ('steamActive()', 'setSteam(bool active)'),
        'client/remix_state.cpp': ('std::lock_guard<std::recursive_mutex>', 'm_state.store(after,std::memory_order_release)'),
        'client/di_hook.cpp': ('allowSteamInputHookChain()', 'allowSteamInputPollingChain()', 'releaseSteamMouseCapture()'),
        'server/steam_window_diagnostics.h': ('selectWindow(HWND real', 'owner(child) != host', 'mode=%s'),
        'server/overlay_presenter.h': ('m_steamNativeInput', 'native-focus acquired=1', 'L4D2BRIDGE_STEAM_ACTIVE'),
        'util/steam_web_diagnostics.h': ('LobbyInvite', 'original[2])(self,dialog)', 'verifiedGuard'),
        'util/steam_workshop_status.h': ('0x11a03', 'menuGuard'),
    }
    hashes = {}
    for name, markers in requirements.items():
        raw = (src / name).read_bytes()
        for marker in markers:
            if marker.encode() not in raw: raise ValueError(f'Required Steam path missing: {name}: {marker}')
        hashes[name] = hashlib.sha256(raw).hexdigest()
    # Protocol identity must no longer pull in the external ReShade vendor sources.
    preparation = (ROOT / 'scripts/prepare_ipc_c32.py').read_text()
    if 'experiments/reshade-input' in preparation or 'patches/reshade-input.patch' in preparation:
        raise ValueError('Experimental ReShade still contributes to prepared build identity')
    result = dict(status='PASS', production_files_scanned=scanned,
                  experimental_reshade_removed=True, steam_source_files=hashes)
    (ROOT / 'work').mkdir(exist_ok=True)
    (ROOT / 'work/steam-only-source-verification.json').write_text(json.dumps(result, indent=2)+'\n')
    print(f'PASS Steam-only production: {scanned} files checked, external ReShade absent, Steam paths present')
    return result

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT / '.deps/dxvk-remix')
    verify(parser.parse_args().source.resolve())
